4	/// git-backed `VCSProviding`, over SwiftGitX (libgit2). Maps `SwiftGitX.*` types into the app-native
5	/// models. Pure Swift — no Rust involved for git.
6	///
7	/// Three reads reach *past* SwiftGitX, all on raw libgit2 (see each type's doc): push state via
8	/// `GitGraph`, because SwiftGitX cannot express the commit RANGE that "not on origin yet" is; commit
9	/// diffs via `GitCommitDiff`, because rename detection has to run on a live `git_diff` and
10	/// SwiftGitX's `Diff` is already materialized and freed by the time we see it; and the working tree's
11	/// ± line counts via `GitDiffStats`, because SwiftGitX's eager `Diff` materializes every changed line
12	/// into a Swift `String` to derive two integers.
13	///
14	/// Errors are caught untyped (`catch { … "\(error)" }`) on purpose: binding SwiftGitX's typed-throws
15	/// error (`catch let e as SwiftGitXError`) trips a Swift 6 SIL ownership error across the async
16	/// boundary.
17	struct GitProvider: VCSProviding {
18	  func log(root: URL, limit: Int) throws -> VCSHistoryPage {
19	    do {
20	      let repo = try Repository.open(at: root)
21	      // A repo with no commits yet (unborn HEAD) is an empty history, not a failure.
22	      if repo.isHEADUnborn { return VCSHistoryPage(commits: [], reachedEnd: true) }
23	
24	      // Take one extra to learn whether more history exists beyond the page.
25	      let window = Array(try repo.log().prefix(max(0, limit) + 1))
26	      let reachedEnd = window.count <= limit
27	      let decorations = Self.decorations(in: repo)
28	      let page = Array(window.prefix(limit))
29	      // Push state for the whole page in one libgit2 revwalk (`HEAD --not refs/remotes/origin/*`).
30	      // A `nil` read is unanswerable — no origin, or a ref we couldn't trust — and EVERY row then reads
31	      // `.unknown`, never a partial answer (a skipped tip could badge a pushed commit as unpushed).
32	      let push = GitGraph.unpushed(root: root, decide: Set(page.map { $0.id.hex }))
33	      let commits = page.map {
34	        Self.map(
35	          $0, refs: decorations[$0.id.hex] ?? [],
36	          pushState: Self.pushState($0.id.hex, in: push))
37	      }
38	      return VCSHistoryPage(
39	        commits: commits, reachedEnd: reachedEnd, pushScope: Self.scope(push?.scope))
40	    } catch {
41	      throw VCSError.io("\(error)")
42	    }
43	  }
44	
45	  func changeset(root: URL, commitID: String) async throws -> VCSChangeset {
46	    try await runBlocking {
47	      do {
48	        let repo = try Repository.open(at: root)
49	        let commit: Commit = try repo.show(id: OID(hex: commitID))
50	        // The file list and line counts come from `GitCommitDiff`, not SwiftGitX: its `repo.diff(commit:)`
51	        // is a plain tree-to-tree diff with no `git_diff_find_similar`, so a committed rename split into
52	        // delete + add (and a root commit came back empty). See that type's doc.
53	        guard let diff = GitCommitDiff.read(root: root, commitID: commit.id.hex) else {
54	          throw VCSError.io("could not read the diff for \(commit.id.hex)")
55	        }
56	        // One-commit push state: `git_graph_reachable_from_any` against the origin tips. There's no page
57	        // here to bound a walk with, which is exactly why this form exists.
58	        let push = GitGraph.isPushed(root: root, commitID: commit.id.hex)
59	        return VCSChangeset(
60	          commit: Self.map(
61	            commit, refs: Self.decorations(in: repo)[commit.id.hex] ?? [],
62	            pushState: push.map { $0.pushed ? .pushed : .unpushed } ?? .unknown),
63	          fullMessage: commit.message,
64	          files: diff.files,
65	          isMerge: ((try? commit.parents.count) ?? 0) > 1,
66	          insertions: diff.insertions,
67	          deletions: diff.deletions,
68	          pushScope: Self.scope(push?.scope)
69	        )
70	      } catch let error as VCSError {
71	        throw error  // already classified (the diff read above) — don't re-wrap it
72	      } catch {
73	        throw VCSError.io("\(error)")
74	      }
75	    }
76	  }
77	
78	  func currentRef(root: URL) async throws -> VCSRef {
79	    try await runBlocking {
80	      do {
81	        let repo = try Repository.open(at: root)
82	        // Unborn HEAD (git init, no commit): HEAD symbolically points at a branch with no commit yet.
83	        // Report that branch name (from config's init.defaultBranch) so a fresh repo still labels.
84	        if repo.isHEADUnborn {
85	          let name = try? repo.config.defaultBranchName
86	          return VCSRef(name: name, kind: name == nil ? .none : .branch)
87	        }
88	        // Attached HEAD → the current branch. `branch.current` throws when HEAD is detached.
89	        if let branch = try? repo.branch.current {
90	          return VCSRef(name: branch.name, kind: .branch)
91	        }
92	        // Detached HEAD → the short commit id (mirrors `git rev-parse --short HEAD`).
93	        let head = try repo.HEAD
94	        return VCSRef(name: head.target.id.abbreviated, kind: .detached)
95	      } catch {
96	        throw VCSError.io("\(error)")
97	      }
98	    }
99	  }
100	
101	  func fileDiff(root: URL, commitID: String, path: String) async throws -> String {
102	    try await runBlocking {
103	      do {
104	        let repo = try Repository.open(at: root)
105	        let commit: Commit = try repo.show(id: OID(hex: commitID))
106	        // Same rename-detected diff the file list is built from (`changeset`), so a row that reads
107	        // "renamed" renders as a rename here too — libgit2 prints the patch in git's own format,
108	        // `rename from`/`rename to` headers included. `""` ⇒ path unchanged in this changeset.
109	        guard let text = GitCommitDiff.patch(root: root, commitID: commit.id.hex, path: path) else {
110	          throw VCSError.io("could not read the diff for \(path) in \(commit.id.hex)")
111	        }
112	        return text
113	      } catch let error as VCSError {
114	        throw error  // already classified (the diff read above) — don't re-wrap it
115	      } catch {
116	        throw VCSError.io("\(error)")
117	      }
118	    }
119	  }
