121	  /// Working-copy per-file diff, as git-format text — the working-copy counterpart of `fileDiff`,
122	  /// built structurally from libgit2 (no subprocess, no `git diff` shell-out). Per-file by
123	  /// construction: it fetches the single path's status delta, then builds just that file's `Patch`
124	  /// (`git_patch_from_blob*`) — never a whole-worktree diff.
125	  ///
126	  /// jj-only `.parent` isn't a git concept (git repos never request it) → unsupported.
127	  func workingFileDiff(root: URL, path: String, base: VCSWorkingDiffBase) async throws -> String {
128	    guard base == .workingCopy else {
129	      throw VCSError.unsupportedRepo("git has no working-copy parent diff")
130	    }
131	    return try await runBlocking {
132	      do {
133	        let repo = try Repository.open(at: root)
134	        // Same status options as `workingStatus`: untracked + rename detection, so the delta type
135	        // matches the badge and a `git mv` reads as one rename (blob→file), not delete + add.
136	        let options: StatusOption = [
137	          .includeUntracked, .recurseUntrackedDirectories, .renamesIndex, .renamesWorkingTree,
138	        ]
139	        guard
140	          let entry = try repo.status(options: options).first(where: {
141	            let d = $0.workingTree ?? $0.index
142	            return d?.newFile.path == path || d?.oldFile.path == path
143	          })
144	        else {
145	          return ""  // path clean / not a working-copy change
146	        }
147	        // A file staged AND further changed in the worktree carries BOTH deltas (HEAD→index,
148	        // index→worktree). Picking either alone (the old `workingTree ?? index`) shows only that
149	        // one leg — e.g. the staged half goes missing. Combine them the same way `.conflicted`
150	        // already reads HEAD→worktree: diff the file's HEAD blob (nil if it's new since HEAD)

