    HStack(spacing: 6) {
      Image(systemName: systemImage).foregroundStyle(.tertiary)
      Text(text).font(.callout).foregroundStyle(.secondary)
    }
    .padding(.vertical, 6).padding(.horizontal, 8)
  }
