import AppKit
import SwiftUI
import XCTest

@testable import Workroom

/// Measures the WORKROOM-2B candidate flagged in TODOS.md for `Views/FilesPanel.swift`:
/// `FileTreeRowView` holds BOTH `@EnvironmentObject var store: AppStore` (used only inside tap/menu
/// closures, never read in the rendered body) and `@ObservedObject var model: FileTreeModel`, over
/// an eager `VStack` capped at 4000 rows — the same shape that turned per-row avatar work into a
/// 2-second History-pane stall. The TODO's own instruction: measure before changing anything.
///
/// Harness mirrors `HistoryRowInvalidationTests` (offscreen `NSHostingView`, the shared `settle`
/// waiter) — `FileTreeModel` is hosted standalone (not `store.fileTree`), fed by a fake
/// `StatusCommandRunning` so no real `git`/`jj` process is ever spawned.
@MainActor
final class FilesPanelInvalidationTests: XCTestCase {

  // MARK: harness

  /// Returns a fixed `git ls-files -z` result for however many paths were configured; the `jj`
  /// branch is never reached because git always succeeds first.
  private final class FixedGitListRunner: StatusCommandRunning, @unchecked Sendable {
    var paths: [String] = []
    func run(_ executable: String, _ args: [String], in directory: String, timeout: TimeInterval)
      async -> CommandResult
    {
      CommandResult(
        stdout: paths.joined(separator: "\0") + "\0", stderr: "", exitCode: 0, timedOut: false)
    }
  }

  private var tempDirs: [String] = []

  override func tearDown() {
    for d in tempDirs { try? FileManager.default.removeItem(atPath: d) }
    tempDirs = []
    super.tearDown()
  }

  /// A real, empty throwaway directory — `FileTreeModel.activate` requires the path to exist on
  /// disk, but the listing itself is entirely faked, so nothing inside it is ever read.
  private func throwawayDir() -> String {
    let path = NSTemporaryDirectory() + "wr-filespanel-\(UUID().uuidString)"
    try? FileManager.default.createDirectory(atPath: path, withIntermediateDirectories: true)
    tempDirs.append(path)
    return path
  }

  /// `settle`'s `RunLoop.current` pump (built for letting AppKit/SwiftUI layout catch up) never gives
  /// `FileTreeModel.reload`'s unstructured `Task` a turn in this plain-XCTest hosting context — a
  /// real `Task.sleep` poll does, mirroring `AppStoreDeleteRaceTests.waitUntil`.
  private func awaitLoaded(_ model: FileTreeModel) async {
    for _ in 0..<200 {
      if model.state == .loaded { return }
      try? await Task.sleep(nanoseconds: 2_000_000)
    }
  }

  /// A `FileTreeModel` activated against `count` FLAT (no subdirectories) synthetic files, so every
  /// one is a visible row with no expansion needed — directly exercising "renders up to 4000 rows
  /// eagerly", not the (also-eager, but separately gated) directory-expansion path.
  private func activatedModel(fileCount count: Int) async -> FileTreeModel {
    let runner = FixedGitListRunner()
    runner.paths = (0..<count).map { "file-\($0).txt" }
    let model = FileTreeModel(runner: runner)
    model.activate(path: throwawayDir())
    await awaitLoaded(model)
    return model
  }

  /// A store with an active selection (so `FilesPanel` clears its "No open terminal" placeholder)
  /// but otherwise uninvolved with the file tree — the model under test is hosted standalone.
  private func makeStore() -> AppStore {
    let store = AppStore()
    store.terminals.makeView = { _, cwd, _ in GhosttySurfaceView(workingDirectory: cwd) }
    let projectPath = "/files-invalidation"
    store.projects = [
      Project(
        path: projectPath, vcs: "git",
        workrooms: [
          Workroom(
            name: "solo", path: "\(projectPath)/solo", vcsName: "workroom/solo", warnings: [])
        ])
    ]
    let target = store.target(for: .workroom(project: projectPath, name: "solo"))!
    _ = store.terminals.addTab(for: target)
    store.selectedTargetID = .workroom(project: projectPath, name: "solo")
    // Not fired automatically by the above in this bare harness (no real window/focus event drives
    // it) — `FilesPanel`'s placeholder gate (`store.inspectorTargetID`) depends on it directly.
    store.refreshSelectionHasTabs()
    return store
  }

  /// Host the real `FilesPanel` offscreen, directly over the given model (not `store.fileTree`).
  private func host(_ store: AppStore, _ model: FileTreeModel) -> (NSWindow, NSView) {
    let root = FilesPanel(model: model)
      .environmentObject(store)
      .environmentObject(store.notifications)
      .frame(width: 280, height: 400)
    let hosting = NSHostingView(rootView: root)
    hosting.frame = NSRect(x: 0, y: 0, width: 280, height: 400)
    let window = NSWindow(
      contentRect: hosting.frame, styleMask: [.titled], backing: .buffered, defer: false)
    window.isReleasedWhenClosed = false
    window.contentView = hosting
    window.makeKeyAndOrderFront(nil)
    return (window, hosting)
  }

  // MARK: measurements

  /// The scale question the TODO poses literally: does the eager `VStack` build every row of a
  /// large tree (unlike a lazy list, which would build only the viewport)?
  func testLargeTreeBuildsEveryVisibleRow() async throws {
    let model = await activatedModel(fileCount: 1000)
    let store = makeStore()
    FileTreeRowView.bodyPasses = 0
    let (window, view) = host(store, model)
    defer { window.close() }
    settle(view)

    XCTAssertEqual(
      FileTreeRowView.bodyPasses, 1000,
      "a 280×400 panel shows ~15 rows, so building all 1000 confirms the VStack is eager — matching "
        + "the Changes/History/Diff pattern, not yet fixed here")
  }

  /// The actual WORKROOM-2B mechanism: does a publish of `AppStore` that says NOTHING about the file
  /// tree still rebuild every row? `store` is read only inside `FileTreeRowView`'s tap/menu closures
  /// today, never in its rendered body — if that's still true, this MUST be zero.
  func testUnrelatedAppStorePublishRebuildsRows() async throws {
    let model = await activatedModel(fileCount: 200)
    let store = makeStore()
    let (window, view) = host(store, model)
    defer { window.close() }
    settle(view)
    XCTAssertGreaterThan(
      FileTreeRowView.bodyPasses, 0, "the fixture must actually render file rows")

    FileTreeRowView.bodyPasses = 0
    // Reassigning a `@Published` property fires `objectWillChange` regardless of value equality —
    // this says nothing whatsoever about the file tree.
    for _ in 0..<10 { store.isLoading.toggle() }
    settle(view)

    XCTAssertEqual(
      FileTreeRowView.bodyPasses, 0,
      "an AppStore publish unrelated to the file tree rebuilt \(FileTreeRowView.bodyPasses) row "
        + "passes — this is the WORKROOM-2B mechanism: `store` is read only inside this row's "
        + "closures, never its body, so ANY AppStore publish (title/activity/notifications/status, "
        + "all far higher-frequency than a file-tree reload) shouldn't touch it at all")
  }

  /// The model's OWN publish, unrelated to any row's own content: does toggling ONE directory's
  /// expansion (which flips `FileTreeModel.expanded`, a single `@Published` `Set` shared by every
  /// row) rebuild siblings that didn't change? No equality gate exists today, so this is expected to
  /// be nonzero — the question this test exists to pin is HOW MANY, as the baseline a future fix's
  /// regression test would tighten.
  func testTogglingOneDirectoryRebuildsSiblingRows() async throws {
    let runner = FixedGitListRunner()
    runner.paths = ["dir/a.txt"] + (0..<200).map { "file-\($0).txt" }
    let model = FileTreeModel(runner: runner)
    model.activate(path: throwawayDir())
    await awaitLoaded(model)
    let store = makeStore()
    let (window, view) = host(store, model)
    defer { window.close() }
    settle(view)
    guard let dir = model.roots.first(where: { $0.isDirectory }) else {
      return XCTFail("fixture must include a directory row to toggle")
    }

    FileTreeRowView.bodyPasses = 0
    model.toggle(dir)
    settle(view)

    // Not a regression assertion (no fix has landed) — just proving the measurement mechanism sees
    // a real, nonzero effect, so the two tests above aren't passing by accident (nothing rendering).
    XCTAssertGreaterThan(
      FileTreeRowView.bodyPasses, 0,
      "toggling a directory's expansion produced no rebuild at all — the fixture likely isn't "
        + "rendering rows")
  }
}

