/// Weak, so a closed window drops out automatically. The surface iteration stays in
/// `TerminalSessions`; `applyActiveTheme()` remains the single chokepoint every trigger routes through.
private let terminalSinks = NSHashTable<TerminalSessions>.weakObjects()

/// Register/unregister a window's terminal sessions for theme sweeps (issue #70).
func registerTerminals(_ sessions: TerminalSessions) { terminalSinks.add(sessions) }
func unregisterTerminals(_ sessions: TerminalSessions) { terminalSinks.remove(sessions) }

init() {
  let isDark = Self.isCurrentAppearanceDark()
  tokens = ThemeTokens(preview: Self.themePreview(named: Self.activeThemeName(isDark: isDark)))
}

// MARK: Resolution (static — also called by GhosttyApp.writeThemeConfig without the instance)

nonisolated static func family(named name: String) -> ThemeFamily? {
  families.first { $0.name == name }
}

/// The active variant file name for an appearance: the selected family's variant for that mode,
/// else the Workroom default. Always sanitised (safe to write into the conf).
nonisolated static func activeThemeName(isDark: Bool) -> String {
  let resolved =
    family(named: Defaults[.themeFamily])?.variant(isDark: isDark)
    ?? family(named: defaultFamilyName)!.variant(isDark: isDark)
  return sanitizedThemeName(resolved)
}

/// Strip anything that would break or inject into the generated `ghostty.conf` (the name is
/// written as `theme = "<name>"`), and reject path separators so a crafted `~/.config` filename
/// can't escape the themes dir.
nonisolated static func sanitizedThemeName(_ name: String) -> String {
  name.filter { $0 != "\"" && $0 != "\n" && $0 != "\r" && $0 != "/" && $0 != "\\" }
}

// MARK: The chokepoint

/// THE single apply path. Every trigger (picker selection, appearance change, first run) routes
/// here. Steps: (1) validate the active name resolves — reset to Workroom if not, so terminal
/// *and* chrome fall back to the *same* theme; (2) recompute chrome tokens; (3) re-theme live
/// terminals (regenerates the conf with the new `theme=` and force-reloads); (4) notify AppKit
/// sites that read `ThemeService.shared.tokens` outside SwiftUI.
func applyActiveTheme(force: Bool = true) {
  validateSelection()
  let isDark = Self.isCurrentAppearanceDark()
  tokens = ThemeTokens(preview: Self.themePreview(named: Self.activeThemeName(isDark: isDark)))
  generation &+= 1
  for sessions in terminalSinks.allObjects { sessions.applyThemeToAll(force: force) }
  NotificationCenter.default.post(name: .themeDidChange, object: nil)
}

func applyFamily(_ name: String) {
  Defaults[.themeFamily] = name
  applyActiveTheme()
}

/// If the stored family no longer resolves (e.g. an old key references a renamed family), reset
/// to the Workroom default so the terminal (ghostty) and chrome don't diverge onto different
/// fallbacks.
private func validateSelection() {
  if Self.family(named: Defaults[.themeFamily]) == nil {
    Defaults[.themeFamily] = Self.defaultFamilyName
  }
}

// MARK: Resolution

/// Parsed previews for the **bundled** dir only, keyed by theme name.
///
/// `ThemePicker` calls `themePreview` twice per row *inside the row body* (`ThemePicker.swift`),
/// and every `FamilyRow` observes `ThemeService.shared` for `tokens` — so each ↑/↓, which applies a
/// theme and replaces `tokens`, invalidates every instantiated row and sent all of them back to
/// disk. With 58 families that is up to 116 synchronous file reads per keypress on the main actor,
/// on top of the conf rewrite + engine reload the apply already does.
///
/// Only the bundled dir is cached, and that is what makes the cache correct rather than merely
/// fast: those files cannot change while the app is running, so an entry can never go stale.
/// `~/.config` is re-read on every call (below) precisely so a user editing their own theme still
/// sees it change.
///

import AppKit
import XCTest

@testable import Workroom

/// `AvatarImageLoader` (WORKROOM-2B follow-up — the status-aware replacement for `AsyncImage`, see
/// TODOS.md): reads the real HTTP status, so a genuine 404 ("no avatar for this address") and a
/// transient failure ("the network dropped") are distinguishable — only the former is cached — and
/// decoded images are cached too. A `URLProtocol` stub means no real network for any of this, exactly
/// the testability gap `AsyncImage` couldn't offer.
final class AvatarImageLoaderTests: XCTestCase {

  /// Thread-safe canned-response registry `StubURLProtocol` reads from — `startLoading()` runs on a
  /// background queue URLSession owns, not the test's own thread.
  private final class StubRegistry: @unchecked Sendable {
    private let lock = NSLock()
    private var responses: [URL: (status: Int, data: Data)] = [:]
    private var errorURLs: Set<URL> = []
    private var callCounts: [URL: Int] = [:]

    func setResponse(status: Int, data: Data, for url: URL) {
      lock.lock()
      responses[url] = (status, data)
      lock.unlock()
    }
    func setError(for url: URL) {
      lock.lock()
      errorURLs.insert(url)
      lock.unlock()
    }
    func clearError(for url: URL) {
      lock.lock()
      errorURLs.remove(url)
      lock.unlock()
    }
    func recordCall(_ url: URL) {
      lock.lock()
      callCounts[url, default: 0] += 1
      lock.unlock()
    }
    func callCount(for url: URL) -> Int {
      lock.lock()
      defer { lock.unlock() }
      return callCounts[url] ?? 0
    }
    func response(for url: URL) -> (status: Int, data: Data)? {
      lock.lock()
      defer { lock.unlock() }
      return responses[url]
    }
    func hasError(for url: URL) -> Bool {
      lock.lock()
      defer { lock.unlock() }
      return errorURLs.contains(url)
    }
  }

  private final class StubURLProtocol: URLProtocol {
    static let registry = StubRegistry()

    override class func canInit(with request: URLRequest) -> Bool { true }
    override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }

    override func startLoading() {
      guard let url = request.url else { return }
      Self.registry.recordCall(url)
      if Self.registry.hasError(for: url) {
        client?.urlProtocol(self, didFailWithError: URLError(.notConnectedToInternet))
        return
      }
      guard let (status, data) = Self.registry.response(for: url) else {
        client?.urlProtocol(self, didFailWithError: URLError(.badURL))
        return
      }
      let response = HTTPURLResponse(
        url: url, statusCode: status, httpVersion: nil, headerFields: nil)!
      client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
      client?.urlProtocol(self, didLoad: data)
      client?.urlProtocolDidFinishLoading(self)
    }
    override func stopLoading() {}
  }

  private func makeSession() -> URLSession {
    let config = URLSessionConfiguration.ephemeral
    config.protocolClasses = [StubURLProtocol.self]
    return URLSession(configuration: config)
  }

  private func pngData(_ color: NSColor) throws -> Data {
    let image = NSImage(size: NSSize(width: 4, height: 4))
    image.lockFocus()
    color.setFill()
    NSRect(x: 0, y: 0, width: 4, height: 4).fill()
    image.unlockFocus()
    guard let tiff = image.tiffRepresentation, let bitmap = NSBitmapImageRep(data: tiff),
      let png = bitmap.representation(using: .png, properties: [:])
    else {
      throw NSError(domain: "AvatarImageLoaderTests", code: 1)
    }
    return png
  }

  @MainActor
  func testSuccessfulLoadDecodesAndCachesTheImage() async throws {
    let url = URL(string: "https://example.com/a.png")!
    StubURLProtocol.registry.setResponse(status: 200, data: try pngData(.red), for: url)
    let loader = AvatarImageLoader(session: makeSession())

    let first = await loader.load(url)
    guard case .image = first else {
      return XCTFail("expected .image, got \(String(describing: first))")
    }

    _ = await loader.load(url)
    XCTAssertEqual(
      StubURLProtocol.registry.callCount(for: url), 1, "a cached image must not re-request")
  }

  @MainActor
  func testGenuine404IsCachedAsNotFound() async throws {
    let url = URL(string: "https://example.com/missing.png")!
    StubURLProtocol.registry.setResponse(status: 404, data: Data(), for: url)
    let loader = AvatarImageLoader(session: makeSession())

    let first = await loader.load(url)
    XCTAssertEqual(first, .notFound)

    _ = await loader.load(url)
    XCTAssertEqual(
      StubURLProtocol.registry.callCount(for: url), 1, "a cached 404 must not re-request")
  }

  @MainActor
  func testTransientNetworkErrorIsNeverCachedAndRetries() async throws {
    let url = URL(string: "https://example.com/flaky.png")!
    StubURLProtocol.registry.setError(for: url)
    let loader = AvatarImageLoader(session: makeSession())

    let first = await loader.load(url)
    XCTAssertNil(first, "a network error must read as transient (nil), never a cached failure")

    // Fix the network: since nothing was cached, the retry must reach the stub again and succeed.
    StubURLProtocol.registry.clearError(for: url)
    StubURLProtocol.registry.setResponse(status: 200, data: try pngData(.blue), for: url)
    let second = await loader.load(url)
    guard case .image = second else { return XCTFail("expected the retry to succeed") }
    XCTAssertEqual(
      StubURLProtocol.registry.callCount(for: url), 2, "a transient failure must be retried")
  }

  @MainActor
  func testNonStandardStatusIsTransientNotCached() async throws {
    let url = URL(string: "https://example.com/ratelimited.png")!
    StubURLProtocol.registry.setResponse(status: 429, data: Data(), for: url)
    let loader = AvatarImageLoader(session: makeSession())

    let result = await loader.load(url)
    XCTAssertNil(result, "a non-200/404 status must read as transient, not a cached failure")
  }

  @MainActor
  func testUndecodableSuccessBodyIsTransientNotCached() async throws {
    let url = URL(string: "https://example.com/corrupt.png")!
    StubURLProtocol.registry.setResponse(status: 200, data: Data([0x00, 0x01, 0x02]), for: url)
    let loader = AvatarImageLoader(session: makeSession())

    let result = await loader.load(url)
    XCTAssertNil(result, "a 200 with an undecodable body must read as transient, not `.notFound`")
  }

  @MainActor
  func testConcurrentLoadsForTheSameURLShareOneRequest() async throws {
    let url = URL(string: "https://example.com/shared.png")!
    StubURLProtocol.registry.setResponse(status: 200, data: try pngData(.green), for: url)
    let loader = AvatarImageLoader(session: makeSession())

    async let a = loader.load(url)
    async let b = loader.load(url)
    let (first, second) = await (a, b)
    guard case .image = first, case .image = second else {
      return XCTFail("both concurrent loads should succeed")
    }
    XCTAssertEqual(
      StubURLProtocol.registry.callCount(for: url), 1,
      "concurrent loads for one URL must share one request")
  }

  @MainActor
  func testCacheEvictsOldestPastCapacity() async throws {
    let loader = AvatarImageLoader(session: makeSession(), capacity: 2)
    let urls = (0..<3).map { URL(string: "https://example.com/\($0).png")! }
    for url in urls {
      StubURLProtocol.registry.setResponse(status: 200, data: try pngData(.red), for: url)
      _ = await loader.load(url)
    }

    // The oldest (urls[0]) should have been evicted past a capacity of 2; loading it again must
    // re-hit the network rather than serve the (evicted) cache entry.
    _ = await loader.load(urls[0])
    XCTAssertEqual(
      StubURLProtocol.registry.callCount(for: urls[0]), 2,
      "the oldest entry should have been evicted past capacity")
  }
}

import CryptoKit
import Defaults
import SwiftUI

extension VCSCommit {
  /// Every author's display name (falling back to email when a name is blank), comma-joined for a
  /// metadata line — so a commit's full authorship is shown, not just the first author.
  var authorNamesDisplay: String {
    authors
      .map { $0.name.isEmpty ? $0.email : $0.name }
      .filter { !$0.isEmpty }
      .joined(separator: ", ")
  }
}

/// A person shown in the UI — a VCS commit author or a GitHub PR reviewer — reduced to what an
/// avatar needs: a display name (initials + tooltip), a stable seed (deterministic fallback colour),
/// and an optional remote image URL. Authors resolve to a Gravatar (by email, `d=404` so unknown
/// emails fall through); reviewers to `github.com/<login>.png`; teams have no image. When the URL is
/// nil, still loading, or 404s/decodes-empty, the coloured initials chip shows instead.
struct AvatarSubject: Hashable {
  let displayName: String
  /// The stable colour seed — email / login (never the display name, which can collide or be empty).
  let seed: String
  let imageURL: URL?

  /// A commit author. Gravatar keyed by email; seed by email (falls back to name when email empty).
  init(author: VCSAuthor, pixelSize: Int) {
    displayName = author.name.isEmpty ? author.email : author.name
    let key = author.email.isEmpty ? author.name : author.email
    seed = key.lowercased()
    imageURL = Self.gravatar(email: author.email, pixelSize: pixelSize)
  }

  /// A GitHub reviewer. A user → `github.com/<login>.png`; a team → no image (initials on the slug).
  init(reviewer identity: Reviewer.Identity, displayName: String, pixelSize: Int) {
    self.displayName = displayName
    switch identity {
    case .user(let login):
      seed = login.lowercased()
      imageURL = Self.githubAvatar(login: login, pixelSize: pixelSize)
    case .team(let slug):
      seed = "team:" + slug.lowercased()
      imageURL = nil
    }
  }

  /// `https://www.gravatar.com/avatar/<md5(lowercased-trimmed-email)>?s=<px>&d=404`. `d=404` makes
  /// Gravatar 404 (not serve an identicon) when it has no image for the address, so the load fails
  /// and the initials chip shows — the same fallback path as an unknown GitHub login.
  private static func gravatar(email: String, pixelSize: Int) -> URL? {
    let normalized = email.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
    guard !normalized.isEmpty else { return nil }
    let hash = hexString(Insecure.MD5.hash(data: Data(normalized.utf8)))
    return URL(string: "https://www.gravatar.com/avatar/\(hash)?s=\(pixelSize)&d=404")
  }

  private static let hexDigits: [UInt8] = Array("0123456789abcdef".utf8)

  /// Lowercase hex, without Foundation's format machinery.
  ///
  /// This was `.map { String(format: "%02x", $0) }.joined()`, which is 16 full format-string parses
  /// (`+[NSString _stringWithValidatedFormat:]` → `__CFStringAppendFormatCore`) per author to produce
  /// 32 characters. That call was the leaf of the WORKROOM-2B App Hang sample, reached from
  /// `HistoryRow.body` via `AvatarSubject.init` once per author per row per body pass.
  ///
  /// Byte-identical to `%02x` by construction: lowercase, zero-padded, exactly two digits per byte,
  /// no locale involvement — which matters because the digest goes straight into the Gravatar URL, so
  /// any drift would silently break every avatar. `internal`, not `private`, so
  /// `AvatarSubjectTests` can pin it against the exact expression it replaced.
  static func hexString<S: Sequence>(_ bytes: S) -> String where S.Element == UInt8 {
    var out: [UInt8] = []
    out.reserveCapacity(32)
    for byte in bytes {
      out.append(hexDigits[Int(byte >> 4)])
      out.append(hexDigits[Int(byte & 0x0F)])
    }
    return String(decoding: out, as: UTF8.self)
  }

  private static func githubAvatar(login: String, pixelSize: Int) -> URL? {
    guard
      let encoded = login.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed),
      !encoded.isEmpty
    else { return nil }
    return URL(string: "https://github.com/\(encoded).png?size=\(pixelSize)")
  }

  /// Initials for the fallback chip: first letters of the first two words, or the first two letters
  /// of a single-word name (e.g. "octocat" → "OC"). "?" when there's nothing to show.
  var initials: String {
    let words = displayName.split(whereSeparator: { $0 == " " || $0 == "\t" })
    guard let first = words.first, let firstChar = first.first else { return "?" }
    if words.count >= 2, let secondChar = words[1].first {
      return String([firstChar, secondChar]).uppercased()
    }
    return String(first.prefix(2)).uppercased()
  }

  /// Deterministic fill colour for the initials chip. Uses a stable FNV-1a hash of the seed (NOT
  /// `String.hashValue`, which is per-process salted and would recolour every launch) mapped onto
  /// the hue wheel at a fixed saturation/brightness that reads on both light and dark themes.
  func fillColor() -> NSColor {
    var hash: UInt64 = 1_469_598_103_934_665_603  // FNV-1a offset basis
    for byte in seed.utf8 {
      hash ^= UInt64(byte)
      hash = hash &* 1_099_511_628_211
    }
    let hue = Double(hash % 360) / 360.0
    return NSColor(hue: hue, saturation: 0.55, brightness: 0.72, alpha: 1)
  }
}

/// Fetches + decodes avatar images, reading the actual HTTP status — unlike `AsyncImage`, whose
/// `.failure` phase carries only an `Error`, so "no avatar for this address" (Gravatar/GitHub 404,
/// requested with `d=404` on purpose — a miss really is a 404) and "the network dropped" used to land
/// identically. That ambiguity is why the OLD mitigation (`AvatarImageFailures`, a session `Set` of
/// failed URLs) had to clear itself on every app activation — it couldn't tell a genuine miss from a
/// transient one, so it could only bound the damage, not fix it. This loader can, and gets image
/// caching (no flicker on re-realization, needed since the History list is a `LazyVStack` — rows are
/// built as they scroll in) for free.
///
/// Session-lifetime, bounded LRU cache (`capacity`): Gravatar/GitHub avatars are 16–54px, so even a
/// few hundred cached decoded images stay small. A cached `.notFound` is permanent for the session (a
/// real 404 doesn't change mid-session); a `nil` result (network error, non-200/404 status, or an
/// undecodable 200 body) is NEVER cached, so the next realization of the row retries it — the same
/// self-healing property the old mitigation had, without needing an app-activation hook to get it.
@MainActor
final class AvatarImageLoader {
  static let shared = AvatarImageLoader()

  enum LoadResult: Equatable {
    case image(NSImage)
    case notFound
  }

  private let session: URLSession
  private let capacity: Int
  private var cache: [URL: LoadResult] = [:]
  /// Oldest-first insertion order, for LRU eviction — a plain array is fine at this scale (capacity
  /// is a few hundred at most).
  private var cacheOrder: [URL] = []
  /// De-duplicates concurrent requests for the same URL (e.g. two rows sharing an author scrolling
  /// into view together) — the second caller awaits the first's in-flight fetch instead of firing a
  /// second request.
  private var inFlight: [URL: Task<LoadResult?, Never>] = [:]

  init(session: URLSession = .shared, capacity: Int = 256) {
    self.session = session
    self.capacity = capacity
  }

  /// `nil` ⇒ transient — the caller should show initials for now; a later realization retries.
  func load(_ url: URL) async -> LoadResult? {
    if let cached = cache[url] { return cached }
    if let existing = inFlight[url] { return await existing.value }
    let task = Task<LoadResult?, Never> { [weak self] in
      await self?.fetch(url)
    }
    inFlight[url] = task
    let result = await task.value
    inFlight[url] = nil
    return result
  }

  private func fetch(_ url: URL) async -> LoadResult? {
    let data: Data
    let response: URLResponse
    do {
      (data, response) = try await session.data(from: url)
    } catch {
      return nil  // transient: network error, cancellation, etc.
    }
    guard let http = response as? HTTPURLResponse else { return nil }
    if http.statusCode == 404 {
      store(.notFound, for: url)
      return .notFound
    }
    guard http.statusCode == 200, let image = NSImage(data: data) else {
      return nil  // transient: a non-200/404 status, or a 200 body that didn't decode
    }
    let result = LoadResult.image(image)
    store(result, for: url)
    return result
  }

  private func store(_ result: LoadResult, for url: URL) {
    if cache[url] == nil {
      cacheOrder.append(url)
      if cacheOrder.count > capacity {
        cache[cacheOrder.removeFirst()] = nil
      }
    }
    cache[url] = result
  }

  /// Test/QA seam: forget every cached result and in-flight request.
  func clearForTesting() {
    cache.removeAll()
    cacheOrder.removeAll()
    inFlight.removeAll()
  }
}

/// A single circular avatar: the remote image once it loads, the coloured initials chip otherwise
/// (nil URL, still loading, a genuine 404, or a transient failure). Decorative — the adjacent name
/// text carries the accessibility label, so the avatar is hidden from VoiceOver and only exposes a
/// hover tooltip.
struct AvatarView: View {
  let subject: AvatarSubject
  var size: CGFloat = 16
  private let theme = ThemeService.shared
  /// Privacy gate: when off, no avatar image is ever requested (the initials chip shows instead), so
  /// viewing an untrusted repo's history can't beacon the viewer to Gravatar/GitHub. See the key doc.
  @Default(.loadRemoteAvatars) private var loadRemoteAvatars
  /// Injected for tests (a real `URLProtocol` stub); defaults to the shared session-lifetime cache.
  var loader = AvatarImageLoader.shared
  @State private var result: AvatarImageLoader.LoadResult?

  /// `.task(id:)` needs ONE Hashable key covering everything that should restart the fetch — the URL
  /// itself, and the privacy gate (so flipping it on mid-session retries immediately rather than
  /// waiting for some unrelated re-identity).
  private var taskKey: String {
    "\(subject.imageURL?.absoluteString ?? "")\u{1F}\(loadRemoteAvatars)"
  }

  var body: some View {
    Group {
      if case .image(let image) = result {
        Image(nsImage: image).resizable().scaledToFill()
      } else {
        initials
      }
    }
    .frame(width: size, height: size)
    .clipShape(Circle())
    .overlay(Circle().strokeBorder(theme.tokens.border, lineWidth: 0.5))
    .help(subject.displayName)
    .accessibilityHidden(true)
    .task(id: taskKey) {
      guard loadRemoteAvatars, let url = subject.imageURL else {
        result = nil
        return
      }
      result = await loader.load(url)
    }
  }

  private var initials: some View {
    let fill = subject.fillColor()
    return Circle()
      .fill(Color(nsColor: fill))
      .overlay(
        Text(subject.initials)
          .font(.system(size: size * 0.42, weight: .semibold, design: .rounded))
          .foregroundStyle(Color(nsColor: ThemeTokens.contrastingForeground(for: fill)))
          .minimumScaleFactor(0.5)
          .padding(1)
      )
  }
}

/// Overlapping circular avatars for a set of people — a commit's authors (jj changes can carry
/// several) or any multi-person context. One subject renders as a lone avatar; more overlap left
/// over right, each with a background-coloured ring so the overlap reads as a stack. Every subject
/// is shown (no cap) — a commit's full author set is always visible.
struct AvatarStack: View {
  let subjects: [AvatarSubject]
  var size: CGFloat = 16
  private let theme = ThemeService.shared

  var body: some View {
    HStack(spacing: -size * 0.35) {
      ForEach(Array(subjects.enumerated()), id: \.offset) { _, subject in
        AvatarView(subject: subject, size: size)
          .overlay(Circle().strokeBorder(theme.tokens.panel, lineWidth: 1.5))
      }
    }
    .accessibilityHidden(true)
  }
}

import AppKit
import SwiftUI
import XCTest

@testable import Workroom

/// The regression net for the WORKROOM-2B candidate flagged in TODOS.md for `Views/FilesPanel.swift`:
/// `FileTreeRowView` used to hold BOTH `@EnvironmentObject var store: AppStore` (read only inside
/// tap/menu closures, never in the rendered body) and `@ObservedObject var model: FileTreeModel`,
/// over an eager `VStack` capped at 4000 rows — the same shape that turned per-row avatar work into a
/// 2-second History-pane stall. Measured before changing anything (per the TODO's own instruction):
/// an unrelated `AppStore` publish rebuilt all 200 visible rows. Fixed the same way History/Changes
/// were — the row now observes nothing, `FilesPanel` hoists `isExpanded` + passes plain closures, and
/// the list is a `LazyVStack` (safe here: rows are fixed-height, unlike `DiffViewer`'s soft-wrapping
/// lines) inside the inspector's own `ScrollView`.
///
/// Harness mirrors `HistoryRowInvalidationTests` (offscreen `NSHostingView`, the shared `settle`
/// waiter for UI settling) — `FileTreeModel` is hosted standalone (not `store.fileTree`), fed by a
/// fake `StatusCommandRunning` so no real `git`/`jj` process is ever spawned. `awaitLoaded` uses a
/// real `Task.sleep` poll instead: `settle`'s `RunLoop.current` pump (built for AppKit/SwiftUI layout)
/// never gives `FileTreeModel.reload`'s unstructured `Task` a turn in this plain-XCTest context.
@MainActor
final class FilesPanelInvalidationTests: XCTestCase {

  // MARK: harness

  /// Returns a fixed `git ls-files -z` result for however many paths were configured; the `jj`
  /// branch is never reached because git always succeeds first.
  private final class FixedGitListRunner: StatusCommandRunning, @unchecked Sendable {
    var paths: [String] = []
    func run(_ executable: String, _ args: [String], in directory: String, timeout: TimeInterval)
      async -> CommandResult
    {
      CommandResult(
        stdout: paths.joined(separator: "\0") + "\0", stderr: "", exitCode: 0, timedOut: false)
    }
  }

  private var tempDirs: [String] = []

  override func tearDown() {
    for d in tempDirs { try? FileManager.default.removeItem(atPath: d) }
    tempDirs = []
    super.tearDown()
  }

  /// A real, empty throwaway directory — `FileTreeModel.activate` requires the path to exist on
  /// disk, but the listing itself is entirely faked, so nothing inside it is ever read.
  private func throwawayDir() -> String {
    let path = NSTemporaryDirectory() + "wr-filespanel-\(UUID().uuidString)"
    try? FileManager.default.createDirectory(atPath: path, withIntermediateDirectories: true)
    tempDirs.append(path)
    return path
  }

  private func awaitLoaded(_ model: FileTreeModel) async {
    for _ in 0..<200 {
      if model.state == .loaded { return }
      try? await Task.sleep(nanoseconds: 2_000_000)
    }
  }

  /// A `FileTreeModel` activated against `count` FLAT (no subdirectories) synthetic files, so every
  /// one is a visible row with no expansion needed — directly exercising "does the list build every
  /// row of a large tree", not the (separately gated) directory-expansion path.
  private func activatedModel(fileCount count: Int) async -> FileTreeModel {
    let runner = FixedGitListRunner()
    runner.paths = (0..<count).map { "file-\($0).txt" }
    let model = FileTreeModel(runner: runner)
    model.activate(path: throwawayDir())
    await awaitLoaded(model)
    return model
  }

  /// A store with an active selection (so `FilesPanel` clears its "No open terminal" placeholder)
  /// but otherwise uninvolved with the file tree — the model under test is hosted standalone.
  private func makeStore() -> AppStore {
    let store = AppStore()
    store.terminals.makeView = { _, cwd, _ in GhosttySurfaceView(workingDirectory: cwd) }
    let projectPath = "/files-invalidation"
    store.projects = [
      Project(
        path: projectPath, vcs: "git",
        workrooms: [
          Workroom(
            name: "solo", path: "\(projectPath)/solo", vcsName: "workroom/solo", warnings: [])
        ])
    ]
    let target = store.target(for: .workroom(project: projectPath, name: "solo"))!
    _ = store.terminals.addTab(for: target)
    store.selectedTargetID = .workroom(project: projectPath, name: "solo")
    // Not fired automatically by the above in this bare harness (no real window/focus event drives
    // it) — `FilesPanel`'s placeholder gate (`store.inspectorTargetID`) depends on it directly.
    store.refreshSelectionHasTabs()
    return store
  }

  /// Host the real `FilesPanel` offscreen, directly over the given model (not `store.fileTree`).
  private func host(_ store: AppStore, _ model: FileTreeModel) -> (NSWindow, NSView) {
    let root = FilesPanel(model: model)
      .environmentObject(store)
      .environmentObject(store.notifications)
      .frame(width: 280, height: 400)
    let hosting = NSHostingView(rootView: root)
    hosting.frame = NSRect(x: 0, y: 0, width: 280, height: 400)
    let window = NSWindow(
      contentRect: hosting.frame, styleMask: [.titled], backing: .buffered, defer: false)
    window.isReleasedWhenClosed = false
    window.contentView = hosting
    window.makeKeyAndOrderFront(nil)
    return (window, hosting)
  }

  // MARK: the hang itself

  /// The actual WORKROOM-2B mechanism: does a publish of `AppStore` that says NOTHING about the file
  /// tree still rebuild every row? `store` is no longer observed by the row at all — this must be
  /// zero, and fails on the pre-fix code (all 200 rows rebuilt).
  func testUnrelatedAppStorePublishRebuildsNoRows() async throws {
    let model = await activatedModel(fileCount: 200)
    let store = makeStore()
    let (window, view) = host(store, model)
    defer { window.close() }
    settle(view)
    XCTAssertGreaterThan(
      FileTreeRowView.bodyPasses, 0, "the fixture must actually render file rows")

    FileTreeRowView.bodyPasses = 0
    // Reassigning a `@Published` property fires `objectWillChange` regardless of value equality —
    // this says nothing whatsoever about the file tree.
    for _ in 0..<10 { store.isLoading.toggle() }
    settle(view)

    XCTAssertEqual(
      FileTreeRowView.bodyPasses, 0,
      "an AppStore publish unrelated to the file tree rebuilt \(FileTreeRowView.bodyPasses) row "
        + "passes — this is WORKROOM-2B: title/activity/notifications/status publishes, all far "
        + "higher-frequency than a file-tree reload, must not touch these rows at all")
  }

  /// The positive half: a real content change (a directory's OWN expansion flipping) must still
  /// rebuild THAT row. The equality gate that gives us zero above could just as easily freeze every
  /// row's contents if it compared the wrong fields.
  func testTogglingADirectoryRebuildsThatRow() async throws {
    let runner = FixedGitListRunner()
    runner.paths = ["dir/a.txt"] + (0..<50).map { "file-\($0).txt" }
    let model = FileTreeModel(runner: runner)
    model.activate(path: throwawayDir())
    await awaitLoaded(model)
    let store = makeStore()
    let (window, view) = host(store, model)
    defer { window.close() }
    settle(view)
    guard let dir = model.roots.first(where: { $0.isDirectory }) else {
      return XCTFail("fixture must include a directory row to toggle")
    }

    FileTreeRowView.bodyPasses = 0
    model.toggle(dir)
    settle(view)

    XCTAssertGreaterThan(
      FileTreeRowView.bodyPasses, 0,
      "toggling a directory's own expansion must rebuild at least that row — an equality gate that "
        + "swallowed this would trade the hang for a chevron that never rotates")
  }

  // MARK: scale

  func testLargeTreeDoesNotBuildEveryRow() async throws {
    let model = await activatedModel(fileCount: 1000)
    let store = makeStore()
    FileTreeRowView.bodyPasses = 0
    let (window, view) = host(store, model)
    defer { window.close() }
    settle(view)

    XCTAssertGreaterThan(FileTreeRowView.bodyPasses, 0, "the panel must render some rows")
    // Deliberately not an exact number — how far past the viewport SwiftUI realizes is its business.
    // "Far fewer than all of them" is the property that matters (mirrors
    // `HistoryRowInvalidationTests.testLargePageDoesNotBuildEveryRow`).
    XCTAssertLessThan(
      FileTreeRowView.bodyPasses, 1000,
      "a 280×400 panel shows ~15 rows, so building all 1000 confirms the list is still eager")
  }

  func testLargeTreeRendersUnderTimeCeiling() async throws {
    let model = await activatedModel(fileCount: 4000)
    let store = makeStore()
    let started = Date()
    let (window, view) = host(store, model)
    defer { window.close() }
    view.layoutSubtreeIfNeeded()
    let elapsed = Date().timeIntervalSince(started)

    XCTAssertLessThan(
      elapsed, 0.25,
      "first layout of a 4000-file (renderCap) tree took \(String(format: "%.3f", elapsed))s on the "
        + "main thread")
  }
}

import SwiftUI

/// The inspector's **Files** section body: the selected repo's working tree as a collapsible,
/// indented list (it lives inside the inspector's own scroll view, so it flattens the tree to rows
/// itself rather than hosting a `List`/`OutlineGroup`). A single click on a file opens it read-only
/// in the main pane (preview), a quick second click persists it, and ⌘-click opens it in the
/// external editor — mirroring the Changes panel. Directory rows toggle expansion.
struct FilesPanel: View {
  @EnvironmentObject var store: AppStore
  @ObservedObject var model: FileTreeModel
  private let theme = ThemeService.shared

  var body: some View {
    Group {
      if store.inspectorTargetID == nil {
        // No active workspace (nothing selected, or the selected workroom has no open tabs) — empty
        // out to match the detail pane's "No terminal" state rather than list a stale workroom.
        placeholder("No open terminal", systemImage: "folder")
      } else {
        switch model.state {
        case .idle:
          placeholder("No workroom selected", systemImage: "folder")
        case .loading:
          HStack(spacing: 6) {
            ProgressView().controlSize(.small)
            Text("Listing files…").font(.callout).foregroundStyle(.secondary)
          }
          .padding(.vertical, 6).padding(.horizontal, 8)
        case .unavailable:
          placeholder("Not a repository", systemImage: "folder.badge.questionmark")
        case .loaded:
          if model.roots.isEmpty {
            placeholder("No files", systemImage: "folder")
          } else {
            fileList
          }
        }
      }
    }
    .frame(maxWidth: .infinity, alignment: .leading)
    // Point the tree at the inspector's active target (nil once all its tabs close → the tree
    // clears), only while Files is the active activity-bar section. Re-runs on either change;
    // `activate` no-ops when already on the path, so re-selecting the same target is instant.
    .task(id: activationKey) {
      guard store.activeInspectorSection == .files else { return }
      let target = store.inspectorTarget
      model.activate(path: target?.path, projectRoot: target.flatMap(store.projectRoot(forTarget:)))
    }
  }

  private var activationKey: String {
    "\(AppStore.targetIDString(for: store.inspectorTargetID) ?? "")"
      + "\u{1F}\(store.activeInspectorSection == .files)"
  }

  /// `LazyVStack`, not `VStack`: rows are fixed-height (single-line, truncated — no soft-wrap, unlike
  /// `DiffViewer`'s lines, where lazy would cache a wrong estimate for a not-yet-materialized wrapping
  /// row — see that type's doc for when lazy is wrong), and this already lives inside the inspector's
  /// own `ScrollView` (see the type doc), which is what makes a `LazyVStack` here lazy at all instead
  /// of behaving like `VStack` with no viewport to bound against.
  private var fileList: some View {
    let rows = model.rows
    let capped = Array(rows.prefix(FileTreeModel.renderCap))
    return LazyVStack(alignment: .leading, spacing: 0) {
      ForEach(capped, id: \.node.path) { row in
        FileTreeRowView(
          row: row, isExpanded: model.expanded.contains(row.node.path),
          onToggle: { model.toggle(row.node) },
          onOpenPreview: { store.openFilePreview(path: row.node.path) },
          onOpenPersistent: { store.openFilePersistent(path: row.node.path) },
          onOpenInEditor: { store.openFileInEditor(path: row.node.path) }
        )
        .equatable()
      }
      if rows.count > capped.count {
        Text("+\(rows.count - capped.count) more — narrow the tree or open in your editor.")
          .font(.caption)
          .foregroundStyle(.secondary)
          .padding(.vertical, 4).padding(.horizontal, 8)
      }
    }
    .padding(.vertical, 2)
  }

  private func placeholder(_ text: String, systemImage: String) -> some View {
    HStack(spacing: 6) {
      Image(systemName: systemImage).foregroundStyle(.tertiary)
      Text(text).font(.callout).foregroundStyle(.secondary)
    }
    .padding(.vertical, 6).padding(.horizontal, 8)
  }
}

/// One row of the Files tree: an indented directory (with a disclosure chevron) or file. Its own
/// view so hover + the click-timing state stay per-row.
///
/// Deliberately `internal`, not `private` (same reason `HistoryRow`/`ChangedFileRow` are): this WAS a
/// WORKROOM-2B eager-stack-plus-per-row-observation candidate (`FilesPanelInvalidationTests` proved it
/// — an unrelated `AppStore` publish rebuilt all 200 visible rows), fixed the same way those two were:
/// no `@EnvironmentObject`/`@ObservedObject` here at all. `FilesPanel` hoists `isExpanded` out of
/// `FileTreeModel` and passes plain closures for the store-dependent actions, so this row observes
/// NOTHING and `.equatable()` at the call site actually has something to gate on.
struct FileTreeRowView: View, Equatable {
  let row: FileTreeRow
  let isExpanded: Bool
  let onToggle: () -> Void
  let onOpenPreview: () -> Void
  let onOpenPersistent: () -> Void
  let onOpenInEditor: () -> Void
  @State private var hovering = false
  /// Tracks the previous click time so a quick second click promotes the preview to a persisted tab
  /// (same manual double-click handling the Changes panel uses).
  @State private var lastClick: Date?
  private let theme = ThemeService.shared

  private var node: FileNode { row.node }

  /// The closures are excluded (same reasoning as `HistoryRow.open`): `FilesPanel` builds them from
  /// `[store, row.node]`, so two rows differing only in closure identity are behaviourally identical.
  static func == (lhs: FileTreeRowView, rhs: FileTreeRowView) -> Bool {
    lhs.row == rhs.row && lhs.isExpanded == rhs.isExpanded
  }

  #if DEBUG
    /// How many times ANY row's body has been evaluated this process — the measurement behind
    /// `FilesPanelInvalidationTests` (WORKROOM-2B follow-up). Debug-only.
    static var bodyPasses = 0
  #endif

  var body: some View {
    #if DEBUG
      Self.bodyPasses += 1
    #endif
    return HStack(spacing: 4) {
      Color.clear.frame(width: CGFloat(row.depth) * 13, height: 1)
      Image(systemName: "chevron.right")
        .font(.system(size: 9, weight: .semibold))
        .foregroundStyle(.secondary)
        .rotationEffect(.degrees(isExpanded ? 90 : 0))
        .frame(width: 10)
        .opacity(node.isDirectory ? 1 : 0)
      Image(systemName: node.isDirectory ? "folder" : "doc")
        .font(.system(size: 11))
        .foregroundStyle(node.isDirectory ? theme.tokens.accent : theme.tokens.fgMuted)
        .frame(width: 15, alignment: .center)
      Text(node.name)
        .font(.callout)
        .foregroundStyle(.primary)
        .lineLimit(1).truncationMode(.middle)
      Spacer(minLength: 0)
    }
    .padding(.vertical, 3).padding(.horizontal, 6)
    .frame(maxWidth: .infinity, alignment: .leading)
    .background(
      Rectangle()
        .fill(hovering ? theme.tokens.rowHover : .clear)
        .padding(.horizontal, -12)
    )
    .contentShape(Rectangle())
    .onHover { hovering = $0 }
    .onTapGesture { handleTap() }
    .help(node.isDirectory ? node.path : "Open \(node.path)")
    .contextMenu {
      if !node.isDirectory {
        Button {
          onOpenInEditor()
        } label: {
          Label("Open in \(ExternalEditor.remembered?.name ?? "Editor")", systemImage: "doc.text")
        }
      }
    }
    .accessibilityElement(children: .ignore)
    .accessibilityAddTraits(.isButton)
    .accessibilityIdentifier(
      "files.\(node.isDirectory ? "dir" : "file").\(node.path)"
    )
    .accessibilityLabel(
      node.isDirectory
        ? "\(node.name), folder, \(isExpanded ? "expanded" : "collapsed")"
        : "\(node.name), file, open")
  }

  private func handleTap() {
    if node.isDirectory {
      onToggle()
      lastClick = nil
      return
    }
    if NSEvent.modifierFlags.contains(.command) {
      onOpenInEditor()  // ⌘-click → external editor, not the in-app viewer
      lastClick = nil
      return
    }
    let now = Date()
    if let last = lastClick, now.timeIntervalSince(last) < 0.35 {
      onOpenPersistent()  // quick second click → persist
      lastClick = nil
    } else {
      onOpenPreview()  // eager: show the read-only preview immediately
      lastClick = now
    }
  }
}

