private final class GatedGHRunner: StatusCommandRunning, @unchecked Sendable {
  private let lock = NSLock()
  private var entered = false
  private var continuation: CheckedContinuation<Void, Never>?

  var enteredGHProbe: Bool {
    lock.lock()
    defer { lock.unlock() }
    return entered
  }

  /// Lets `run()` return. No-op if the probe hasn't reached the await yet.
  func release() {
    lock.lock()
    let cont = continuation
    continuation = nil
    lock.unlock()
    cont?.resume()
  }

  func run(_ executable: String, _ args: [String], in directory: String, timeout: TimeInterval)
    async -> CommandResult
  {
    guard executable == "gh", args.contains("auth") else {
      return CommandResult(stdout: "", stderr: "", exitCode: 0, timedOut: false)
    }
    lock.lock()
    entered = true
    lock.unlock()
    await withCheckedContinuation { (cont: CheckedContinuation<Void, Never>) in
      lock.lock()
      continuation = cont
      lock.unlock()
    }
    return CommandResult(stdout: #"{"hosts":{}}"#, stderr: "", exitCode: 0, timedOut: false)
  }
}

import XCTest

@testable import Workroom

/// Counts in-flight `workingStatus` calls and records the peak seen — the invariant
/// `AppStore.runLocalSweep`'s `cap`-bounded `withTaskGroup` fan-out must hold, and had ZERO test
/// coverage before this file (confirmed by grep: no hits for `runLocalSweep`/`localConcurrency` in
/// this test target). Shared by any status double that needs to prove it never over-runs.
private final class InFlightCounter: @unchecked Sendable {
  private let lock = NSLock()
  private var current = 0
  private(set) var peak = 0

  func enter() {
    lock.lock()
    current += 1
    peak = max(peak, current)
    lock.unlock()
  }
  func leave() {
    lock.lock()
    current -= 1
    lock.unlock()
  }
}

/// A `GitStatusReading` double that holds briefly while counting concurrent callers — long enough
/// that more than `cap` probes would visibly overlap if the fan-out weren't actually bounded, short
/// enough the test doesn't feel it (8 items / cap 5 ⇒ two sequential batches of ~20ms).
private struct CountingGitStatus: GitStatusReading {
  let counter: InFlightCounter
  func workingStatus(root: URL) throws -> GitWorkingStatus {
    counter.enter()
    defer { counter.leave() }
    Thread.sleep(forTimeInterval: 0.02)
    return GitWorkingStatus(
      dirty: false, conflicted: false, files: [], branch: nil, insertions: nil, deletions: nil)
  }
}

/// Reports every tool as missing (exit 127) so `refreshGitHubCLI` resolves to "not available" and
/// the sweep's CI stage never fires a real `gh` process — this test is only about the LOCAL stage's
/// concurrency bound.
private struct MissingToolRunner: StatusCommandRunning {
  func run(_ executable: String, _ args: [String], in directory: String, timeout: TimeInterval)
    async -> CommandResult
  {
    CommandResult(stdout: "", stderr: "", exitCode: CommandResult.commandNotFound, timedOut: false)
  }
}

/// REGRESSION (Muxy test-practices review, filed in TODOS.md — "N-in-flight concurrency accounting
/// test for status sweeps"): `WorkroomStatusResolver.resolveGit`/`resolveJJ` called `GitProvider()`/
/// `RustJJProvider()` directly, bypassing any injection seam, so this invariant was untestable until
/// `GitStatusReading`/`JJStatusReading` existed.
final class WorkroomStatusConcurrencyTests: XCTestCase {
  private var dirs: [String] = []

  override func tearDown() {
    for d in dirs { try? FileManager.default.removeItem(atPath: d) }
    dirs = []
    super.tearDown()
  }

  /// A throwaway, empty directory standing in for a project root — `resolveLocal`'s `fileExists`
  /// guard must pass, but nothing inside it is ever read (the injected double never touches disk).
  private func throwawayProject(_ name: String) -> Project {
    let path = NSTemporaryDirectory() + "wr-cap-\(name)-\(UUID().uuidString)"
    try? FileManager.default.createDirectory(atPath: path, withIntermediateDirectories: true)
    dirs.append(path)
    return Project(path: path, vcs: "git", workrooms: [])
  }

  /// More work items than the sweep's cap, across DIFFERENT projects (so `JJSnapshotGate`'s
  /// per-project serialization can't be mistaken for the thing bounding concurrency — these are all
  /// git anyway, which is never gated): asserts `runLocalSweep` never lets more than 5 local probes
  /// run at once, and that the fan-out actually overlaps at all (else this would pass even fully
  /// serial, proving nothing).
  @MainActor
  func testLocalSweepNeverExceedsItsConcurrencyCap() async {
    let store = AppStore()
    store.projects = (0..<8).map { throwawayProject("\($0)") }

    let counter = InFlightCounter()
    store.statusResolver = WorkroomStatusResolver(
      runner: MissingToolRunner(), gitStatus: CountingGitStatus(counter: counter))

    store.refreshWorkroomStatuses(force: true)
    await store.statusSweepTask?.value

    // Mirrors `AppStore.localConcurrency` (`AppStore+WorkroomStatus.swift`), which is `fileprivate`
    // and so not reachable here by name — a change to that constant should update this literal too.
    XCTAssertLessThanOrEqual(
      counter.peak, 5, "runLocalSweep let more than its cap of 5 local probes run at once")
    XCTAssertGreaterThan(
      counter.peak, 1,
      "the fan-out never actually overlapped — this test would pass even against a fully serial "
        + "sweep, so it isn't proving the cap does any work")
  }
}

func resolveCI(
  path: String, vcs: String, projectRoot: String, branch: String?, nameWithOwner: String? = nil
) async -> CIResolution {
  guard
    let target = await ghProbeTarget(
      path: path, vcs: vcs, projectRoot: projectRoot, branch: branch)
  else { return .absent }
  guard let head = await ciMatchCommit(path: path, vcs: vcs, branch: target.branch) else {
    return .absent
  }
  // Use the caller's cached `owner/repo` when given (the sweep's per-project cache); otherwise
  // resolve it inline. (`??` can't wrap an `await` — its rhs is a non-async autoclosure.)
  let resolvedNWO: String?
  if let nameWithOwner {
    resolvedNWO = nameWithOwner
  } else {
    resolvedNWO = await resolveNameWithOwner(in: target.dir)
  }
  guard let nwo = resolvedNWO, let slash = nwo.firstIndex(of: "/") else { return .absent }
  let owner = String(nwo[..<slash])
  let name = String(nwo[nwo.index(after: slash)...])
  guard !owner.isEmpty, !name.isEmpty else { return .absent }

  let r = await runner.run(
    "gh",
    [
      "api", "graphql", "-f",
      "query=\(Self.checkRollupQuery(owner: owner, name: name, oid: head))",
    ],
    in: target.dir, timeout: ciTimeout)
  return Self.classifyCheckRollup(r)
}

/// The repo's `owner/repo` for the GraphQL rollup lookup, from `gh repo view` in the probe dir
/// (resolves via the dir's git remote — works for git worktrees and a jj colocated project root).
/// The sweep caches this per project; `resolveCI` falls back to calling it inline. `nil` ⇒ no
/// remote / not a gh repo ⇒ caller treats CI as absent.
func resolveNameWithOwner(in dir: String) async -> String? {
  let r = await runner.run(
    "gh", ["repo", "view", "--json", "nameWithOwner", "-q", ".nameWithOwner"], in: dir,
    timeout: ciTimeout)
  guard r.ok else { return nil }
  let s = r.stdout.trimmingCharacters(in: .whitespacesAndNewlines)
  return s.isEmpty ? nil : s
}

/// GraphQL query for a commit's status-check rollup state. Uses `repository(owner:name:)` +
/// `object(oid:)` so it runs against whatever host `gh` resolves for the repo (github.com or GHE),
/// no hardcoded URL. Mirrors the `reviewURLQuery` style (interpolated, trusted inputs: repo names
/// can't contain quotes; `oid` is a hex sha).
static func checkRollupQuery(owner: String, name: String, oid: String) -> String {
  "{repository(owner:\"\(owner)\",name:\"\(name)\"){object(oid:\"\(oid)\"){... on Commit{statusCheckRollup{state}}}}}"
}

/// The pull request for `branch`. Like `resolveCI`, `vcs`/`projectRoot` pick where `gh` runs (a
/// jj workspace has no `.git` of its own, so `gh` must run from the colocated project root). `gh
/// pr list --head` returns a JSON array — empty when the branch has no PR — so "no PR" is a clean
/// `.absent`, not an error.
func resolvePR(path: String, vcs: String, projectRoot: String, branch: String?) async
  -> PRResolution
{
  let res = await resolvePRRaw(path: path, vcs: vcs, projectRoot: projectRoot, branch: branch)
  return await enrichPR(res, path: path, vcs: vcs, projectRoot: projectRoot)
}

/// The classified PR (`gh pr list`) *without* the reviewer-permalink enrichment round-trip. The
/// selection flow uses this so it has the PR `number` immediately — letting `resolveChecks` and the
/// (slower, conditional) reviewer-URL enrichment run concurrently instead of checks waiting behind
/// enrichment (issue #75, Codex #5). `resolvePR` composes this + `enrichPR` to preserve its old
/// behaviour for any other caller.

