  /// committing the result, A's stale image lands in `result` after B has already taken over the
  /// slot — the wrong person's avatar. This is XCTestCase, not XCTestCase-@MainActor async in the
  /// class header, so each `settle` call actually pumps the run loop the hosted `.task` needs.
  func testStaleInFlightFetchNeverOverwritesANewerSubjectInTheSameSlot() throws {
    let emailA = "author-a@example.com"
    let emailB = "author-b@example.com"
