    let urlB = gravatarURL(email: emailB)
    StubURLProtocol.registry.setResponse(status: 200, data: try pngData(.red), for: urlA)
    StubURLProtocol.registry.setResponse(status: 200, data: try pngData(.blue), for: urlB)
