struct AvatarView: View {
  let subject: AvatarSubject
  var size: CGFloat = 16
  private let theme = ThemeService.shared
  /// Privacy gate: when off, no avatar image is ever requested (the initials chip shows instead), so
  /// viewing an untrusted repo's history can't beacon the viewer to Gravatar/GitHub. See the key doc.
  @Default(.loadRemoteAvatars) private var loadRemoteAvatars
  /// Injected for tests (a real `URLProtocol` stub); defaults to the shared session-lifetime cache.
  var loader = AvatarImageLoader.shared
  @State private var result: AvatarImageLoader.LoadResult?
  /// The `taskKey` of whichever `.task(id:)` invocation most recently started a fetch at this
  /// view-identity slot — a generation token, NOT SwiftUI's own cancellation. Measured (see
  /// `lastCancelObserved` history in git blame): an in-place `subject` swap at a stable slot
  /// position does not actually cancel the outgoing `.task`'s `Task` — `Task.isCancelled` reads
  /// `false` throughout its remaining lifetime — so a guard keyed on it is dead code. This token
  /// works regardless of whether SwiftUI ever delivers real cancellation, because it's compared
  /// against `@State`, which (like `result`) survives the slot being reused for a new subject.
  @State private var activeTaskKey: String?

  #if DEBUG
    /// The last value actually committed to `result` by ANY `AvatarView` instance — the measurement
    /// seam behind the stale-in-flight-fetch regression test. Only meaningful in a test hosting a
    /// single `AvatarView` at a time (a real app can have many on screen at once); a global rather
    /// than per-instance because `body` has no stable handle to key a per-instance record by.
    /// Debug-only.
    static var lastCommittedResult: AvatarImageLoader.LoadResult?
  #endif

  /// `.task(id:)` needs ONE Hashable key covering everything that should restart the fetch — the URL
  /// itself, and the privacy gate (so flipping it on mid-session retries immediately rather than
  /// waiting for some unrelated re-identity).
  private var taskKey: String {
    "\(subject.imageURL?.absoluteString ?? "")\u{1F}\(loadRemoteAvatars)"
  }

  var body: some View {
    Group {
      if case .image(let image) = result {
        Image(nsImage: image).resizable().scaledToFill()
      } else {
        initials
      }
    }
    .frame(width: size, height: size)
    .clipShape(Circle())
    .overlay(Circle().strokeBorder(theme.tokens.border, lineWidth: 0.5))
    .help(subject.displayName)
    .accessibilityHidden(true)
    .task(id: taskKey) {
      guard loadRemoteAvatars, let url = subject.imageURL else {
        activeTaskKey = taskKey
        result = nil
        return
      }
      let myKey = taskKey
      activeTaskKey = myKey
      print("DIAGNOSTIC task started myKey=\(myKey)")
      let loaded = await loader.load(url)
      print("DIAGNOSTIC task resumed myKey=\(myKey) activeTaskKey=\(String(describing: activeTaskKey)) loaded=\(String(describing: loaded))")
